CREATE TRIGGER IF NOT EXISTS trg_event_revision_continuity BEFORE INSERT ON event_revisions WHEN NOT EXISTS (SELECT 1 FROM event_revisions existing WHERE existing.revision_id = NEW.revision_id) BEGIN SELECT CASE WHEN NEW.revision_number != (SELECT COALESCE(MAX(revision_number), 0) + 1 FROM event_revisions WHERE event_id = NEW.event_id) THEN RAISE(ABORT, 'event revision number must extend the latest revision by one') WHEN NEW.revision_number = 1 AND NEW.previous_revision_id IS NOT NULL THEN RAISE(ABORT, 'first event revision must not reference a previous revision') WHEN NEW.revision_number > 1 AND COALESCE(NEW.previous_revision_id, '') != COALESCE((SELECT revision_id FROM event_revisions WHERE event_id = NEW.event_id ORDER BY revision_number DESC LIMIT 1), '') THEN RAISE(ABORT, 'event revision previous_revision_id must reference the latest revision') WHEN EXISTS (SELECT 1 FROM event_revisions latest WHERE latest.event_id = NEW.event_id AND latest.revision_number = (SELECT MAX(revision_number) FROM event_revisions WHERE event_id = NEW.event_id) AND julianday(NEW.observed_at) < julianday(latest.observed_at)) THEN RAISE(ABORT, 'event revision observed_at must not move backwards') WHEN EXISTS (SELECT 1 FROM market_events current_event WHERE current_event.event_id = NEW.event_id AND current_event.current_revision_id IS NOT NULL AND julianday(NEW.observed_at) < julianday(current_event.updated_at)) THEN RAISE(ABORT, 'event revision is older than the current event projection') END; END;
